/* ============================================
   ShiftWise — Restaurant Team Management SaaS
   Design System & Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary: #0051C3;
  --primary-dark: #003d94;
  --accent: #DE5052;
  --accent-dark: #c23e40;
  --white: #FFFFFF;
  --gray-50: #F8FAFC;
  --gray-100: #F1F5F9;
  --gray-200: #E2E8F0;
  --gray-300: #CBD5E1;
  --gray-400: #94A3B8;
  --gray-500: #64748B;
  --gray-600: #475569;
  --gray-700: #334155;
  --gray-800: #1E293B;
  --gray-900: #0F172A;
  --success: #10B981;
  --warning: #F59E0B;
  --font-heading: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);
  --shadow-md: 0 4px 12px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 12px 32px rgba(15, 23, 42, 0.12);
  --shadow-xl: 0 24px 48px rgba(15, 23, 42, 0.16);
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--gray-700);
  background: var(--white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: var(--primary);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--primary-dark);
}

ul, ol {
  list-style: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  font-weight: 700;
  line-height: 1.2;
  color: var(--gray-900);
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(2rem, 4vw, 3rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--gray-600);
  max-width: 65ch;
}

.text-center { text-align: center; }
.text-white { color: var(--white); }
.text-white p { color: rgba(255,255,255,0.85); }

/* Container */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-family: var(--font-heading);
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
  white-space: nowrap;
}

.btn-primary {
  background: var(--primary);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(0, 81, 195, 0.3);
}

.btn-primary:hover {
  background: var(--primary-dark);
  color: var(--white);
  transform: translateY(-1px);
  box-shadow: 0 6px 20px rgba(0, 81, 195, 0.35);
}

.btn-accent {
  background: var(--accent);
  color: var(--white);
  box-shadow: 0 4px 14px rgba(222, 80, 82, 0.3);
}

.btn-accent:hover {
  background: var(--accent-dark);
  color: var(--white);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--primary);
  border: 2px solid var(--primary);
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.btn-white {
  background: var(--white);
  color: var(--primary);
}

.btn-white:hover {
  background: var(--gray-100);
  color: var(--primary-dark);
}

.btn-large {
  padding: 16px 36px;
  font-size: 1rem;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: box-shadow var(--transition);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--gray-900);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--primary);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 1.125rem;
}

.logo:hover { color: var(--gray-900); }

.nav-desktop {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  position: relative;
}

.nav-desktop a:hover,
.nav-desktop a.active {
  color: var(--gray-900);
}

.nav-desktop a.active::after {
  content: '';
  position: absolute;
  bottom: -6px;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--primary);
  border-radius: 2px;
}

.nav-cta {
  display: flex;
  align-items: center;
  gap: 16px;
}

/* Mobile Nav Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
  z-index: 1001;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--gray-800);
  border-radius: 2px;
  transition: all var(--transition);
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav Drawer */
.nav-mobile {
  position: fixed;
  top: 0;
  right: -100%;
  width: 80%;
  max-width: 320px;
  height: 100vh;
  background: var(--white);
  box-shadow: var(--shadow-xl);
  padding: 96px 32px 32px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: right var(--transition);
  z-index: 999;
}

.nav-mobile.open {
  right: 0;
}

.nav-mobile a {
  padding: 14px 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--gray-800);
  border-bottom: 1px solid var(--gray-100);
}

.nav-mobile a:hover,
.nav-mobile a.active {
  color: var(--primary);
}

.nav-mobile .btn {
  margin-top: 16px;
  justify-content: center;
}

.overlay {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.4);
  opacity: 0;
  visibility: hidden;
  transition: all var(--transition);
  z-index: 998;
}

.overlay.active {
  opacity: 1;
  visibility: visible;
}

/* Hero Section */
.hero {
  position: relative;
  padding: 160px 0 100px;
  background: linear-gradient(165deg, var(--gray-50) 0%, var(--white) 50%, #EFF6FF 100%);
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -20%;
  right: -10%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0, 81, 195, 0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.hero-content h1 {
  margin-bottom: 20px;
}

.hero-content p {
  font-size: 1.125rem;
  margin-bottom: 32px;
  color: var(--gray-500);
}

.hero-buttons {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}

.hero-visual {
  position: relative;
}

.hero-visual-placeholder {
  width: 100%;
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 4rem;
  box-shadow: var(--shadow-lg);
}

/* Section Base */
.section {
  padding: 96px 0;
}

.section-header {
  text-align: center;
  max-width: 640px;
  margin: 0 auto 64px;
}

.section-header h2 {
  margin-bottom: 16px;
}

.section-header p {
  font-size: 1.125rem;
  color: var(--gray-500);
}

/* Features Grid */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 32px;
}

.feature-card {
  padding: 40px 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  transition: all var(--transition);
}

.feature-card:hover {
  border-color: var(--gray-300);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.feature-icon {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 24px;
}

.feature-icon.blue { background: #EFF6FF; color: var(--primary); }
.feature-icon.red { background: #FEF2F2; color: var(--accent); }
.feature-icon.green { background: #ECFDF5; color: var(--success); }
.feature-icon.amber { background: #FFFBEB; color: var(--warning); }

.feature-card h3 {
  margin-bottom: 12px;
}

.feature-card p {
  font-size: 0.9375rem;
  color: var(--gray-500);
}

/* How It Works */
.how-it-works {
  background: var(--gray-50);
}

.steps-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.step {
  text-align: center;
  position: relative;
}

.step-number {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: var(--primary);
  color: var(--white);
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.step h3 {
  margin-bottom: 12px;
}

.step p {
  font-size: 0.9375rem;
  color: var(--gray-500);
  max-width: 280px;
  margin: 0 auto;
}

/* Testimonials */
.testimonials {
  background: var(--gray-900);
  color: var(--white);
  overflow: hidden;
}

.testimonials h2 {
  color: var(--white);
}

.testimonial-carousel {
  position: relative;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  min-width: 100%;
  padding: 0 16px;
  text-align: center;
}

.testimonial-card blockquote {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 500;
  line-height: 1.5;
  color: var(--white);
  margin-bottom: 32px;
  font-style: italic;
}

.testimonial-author {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.testimonial-author strong {
  color: var(--white);
  font-size: 1rem;
}

.testimonial-author span {
  color: var(--gray-400);
  font-size: 0.875rem;
}

.testimonial-nav {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 48px;
}

.testimonial-nav button {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  border: 1px solid var(--gray-700);
  background: transparent;
  color: var(--white);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}

.testimonial-nav button:hover {
  background: var(--white);
  color: var(--gray-900);
}

.testimonial-dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 24px;
}

.testimonial-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-600);
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.testimonial-dot.active {
  background: var(--white);
  width: 24px;
  border-radius: 4px;
}

/* Stats Banner */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  text-align: center;
}

.stat-item h3 {
  font-size: clamp(2.5rem, 5vw, 3.5rem);
  font-weight: 800;
  color: var(--primary);
  margin-bottom: 8px;
}

.stat-item p {
  font-size: 0.9375rem;
  color: var(--gray-500);
  font-weight: 500;
}

/* Pricing */
.pricing-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  margin-bottom: 48px;
}

.pricing-toggle span {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-500);
  transition: color var(--transition);
}

.pricing-toggle span.active {
  color: var(--gray-900);
  font-weight: 600;
}

.toggle-switch {
  position: relative;
  width: 52px;
  height: 28px;
  background: var(--gray-200);
  border-radius: 14px;
  cursor: pointer;
  transition: background var(--transition);
  border: none;
}

.toggle-switch.active {
  background: var(--primary);
}

.toggle-switch::after {
  content: '';
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  background: var(--white);
  border-radius: 50%;
  transition: transform var(--transition);
  box-shadow: var(--shadow-sm);
}

.toggle-switch.active::after {
  transform: translateX(24px);
}

.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  align-items: start;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
}

.pricing-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: 0 0 0 2px var(--primary), var(--shadow-lg);
  transform: scale(1.03);
}

.pricing-card.featured:hover {
  transform: scale(1.03) translateY(-4px);
}

.pricing-badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 6px 16px;
  border-radius: 20px;
}

.pricing-card h3 {
  margin-bottom: 8px;
}

.pricing-card .price {
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 4px;
}

.pricing-card .price-period {
  font-size: 0.875rem;
  color: var(--gray-400);
  margin-bottom: 24px;
}

.pricing-card .price-note {
  font-size: 0.8125rem;
  color: var(--success);
  font-weight: 600;
  margin-bottom: 24px;
}

.pricing-features {
  margin-bottom: 32px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 0;
  font-size: 0.9375rem;
  color: var(--gray-600);
  border-bottom: 1px solid var(--gray-100);
}

.pricing-features li:last-child {
  border-bottom: none;
}

.pricing-features li.included::before {
  content: '✓';
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #ECFDF5;
  color: var(--success);
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.pricing-features li.not-included {
  color: var(--gray-400);
}

.pricing-features li.not-included::before {
  content: '—';
  width: 20px;
  text-align: center;
  color: var(--gray-300);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

/* Pricing Table (detailed) */
.pricing-table-wrapper {
  overflow-x: auto;
  margin-top: 64px;
}

.pricing-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 600px;
}

.pricing-table th,
.pricing-table td {
  padding: 16px 24px;
  text-align: left;
  border-bottom: 1px solid var(--gray-200);
}

.pricing-table th {
  font-weight: 600;
  color: var(--gray-900);
  background: var(--gray-50);
}

.pricing-table td {
  color: var(--gray-600);
}

.pricing-table td.check {
  color: var(--success);
  font-weight: 700;
}

.pricing-table td.dash {
  color: var(--gray-300);
}

/* FAQ */
.faq {
  background: var(--gray-50);
}

.faq-list {
  max-width: 768px;
  margin: 0 auto;
}

.faq-item {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
}

.faq-question {
  width: 100%;
  padding: 20px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: none;
  border: none;
  font-family: var(--font-heading);
  font-size: 1rem;
  font-weight: 600;
  color: var(--gray-900);
  cursor: pointer;
  text-align: left;
}

.faq-question:hover {
  background: var(--gray-50);
}

.faq-icon {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: transform var(--transition);
  flex-shrink: 0;
}

.faq-item.open .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition), padding var(--transition);
}

.faq-item.open .faq-answer {
  max-height: 300px;
  padding: 0 24px 20px;
}

.faq-answer p {
  color: var(--gray-500);
  font-size: 0.9375rem;
}

/* CTA Section */
.cta-section {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  padding: 96px 0;
  text-align: center;
}

.cta-section h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-section p {
  color: rgba(255, 255, 255, 0.85);
  font-size: 1.125rem;
  margin: 0 auto 32px;
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--gray-400);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand p {
  color: var(--gray-400);
  margin-top: 16px;
  font-size: 0.9375rem;
}

.footer-links h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 20px;
}

.footer-links a {
  display: block;
  color: var(--gray-400);
  font-size: 0.875rem;
  padding: 6px 0;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid var(--gray-800);
  padding-top: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
}

/* Contact Page */
.contact-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: start;
}

.contact-info h3 {
  margin-bottom: 24px;
}

.contact-method {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  margin-bottom: 24px;
}

.contact-method-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: #EFF6FF;
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.contact-method h4 {
  margin-bottom: 4px;
  color: var(--gray-900);
}

.contact-method p {
  color: var(--gray-500);
  font-size: 0.9375rem;
}

.form-group {
  margin-bottom: 20px;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
  margin-bottom: 8px;
}

.form-group label .required {
  color: var(--accent);
}

.form-group input,
.form-group textarea,
.form-group select {
  width: 100%;
  padding: 12px 16px;
  font-family: var(--font-body);
  font-size: 0.9375rem;
  color: var(--gray-900);
  background: var(--white);
  border: 1px solid var(--gray-300);
  border-radius: var(--radius-md);
  transition: border-color var(--transition), box-shadow var(--transition);
}

.form-group input:focus,
.form-group textarea:focus,
.form-group select:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.1);
}

.form-group input.error,
.form-group textarea.error,
.form-group select.error {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(222, 80, 82, 0.1);
}

.error-message {
  font-size: 0.8125rem;
  color: var(--accent);
  margin-top: 6px;
}

.form-group textarea {
  resize: vertical;
  min-height: 120px;
}

.form-success {
  display: none;
  padding: 24px;
  background: #ECFDF5;
  border: 1px solid var(--success);
  border-radius: var(--radius-md);
  text-align: center;
}

.form-success.show {
  display: block;
}

.form-success h3 {
  color: var(--success);
  margin-bottom: 8px;
}

.form-success p {
  color: var(--gray-600);
}

/* Office Locations */
.offices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.office-card {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  text-align: center;
}

.office-card h4 {
  margin-bottom: 8px;
}

.office-card p {
  color: var(--gray-500);
  font-size: 0.9375rem;
}

/* About Page */
.mission-section {
  background: var(--gray-50);
}

.mission-content {
  max-width: 768px;
  margin: 0 auto;
  text-align: center;
}

.mission-content p {
  font-size: 1.25rem;
  line-height: 1.8;
  color: var(--gray-600);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.team-card {
  text-align: center;
}

.team-avatar {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  margin: 0 auto 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-size: 2.5rem;
  font-weight: 700;
}

.team-card h4 {
  margin-bottom: 4px;
}

.team-card p {
  color: var(--gray-500);
  font-size: 0.9375rem;
}

/* Feature Detail */
.feature-detail {
  padding: 80px 0;
}

.feature-detail:nth-child(even) {
  background: var(--gray-50);
}

.feature-detail-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}

.feature-detail-grid.reverse {
  direction: rtl;
}

.feature-detail-grid.reverse > * {
  direction: ltr;
}

.feature-detail-visual {
  width: 100%;
  aspect-ratio: 16/10;
  background: linear-gradient(135deg, var(--gray-100) 0%, var(--gray-200) 100%);
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.feature-detail-content h3 {
  margin-bottom: 16px;
}

.feature-detail-content p {
  color: var(--gray-500);
  margin-bottom: 24px;
}

.feature-detail-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 0;
  color: var(--gray-600);
  font-size: 0.9375rem;
}

.feature-detail-list li::before {
  content: '✓';
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #ECFDF5;
  color: var(--success);
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.integration-category {
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
}

.integration-category h4 {
  margin-bottom: 16px;
  display: flex;
  align-items: center;
  gap: 10px;
}

.integration-category ul li {
  padding: 6px 0;
  color: var(--gray-500);
  font-size: 0.9375rem;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-inner,
  .feature-detail-grid,
  .contact-grid {
    grid-template-columns: 1fr;
    gap: 48px;
  }

  .feature-detail-grid.reverse {
    direction: ltr;
  }

  .steps-grid,
  .stats-grid,
  .team-grid,
  .offices-grid,
  .integrations-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .pricing-grid {
    grid-template-columns: 1fr;
    max-width: 480px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }

  .pricing-card.featured:hover {
    transform: translateY(-4px);
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-desktop,
  .nav-cta .btn-outline {
    display: none;
  }

  .nav-toggle {
    display: flex;
  }

  .hero {
    padding: 120px 0 64px;
  }

  .hero-buttons {
    flex-direction: column;
  }

  .btn {
    width: 100%;
  }

  .section {
    padding: 64px 0;
  }

  .steps-grid,
  .stats-grid,
  .team-grid,
  .offices-grid,
  .integrations-grid,
  .features-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
    gap: 32px;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }

  .pricing-table-wrapper {
    margin-top: 48px;
  }
}

/* Animations */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(24px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-in {
  animation: fadeInUp 0.6s ease-out forwards;
}

/* Utility */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/**
 * ShiftWise — Main JavaScript
 * Handles navigation, pricing toggle, FAQ accordion, testimonial carousel, contact form, and animations.
 */

document.addEventListener('DOMContentLoaded', () => {
  initHeader();
  initMobileNav();
  initPricingToggle();
  initFAQAccordion();
  initTestimonialCarousel();
  initContactForm();
  initScrollAnimations();
  initCountUp();
});

/* ========== Header Scroll Effect ========== */
function initHeader() {
  const header = document.querySelector('.header');
  if (!header) return;

  let ticking = false;
  window.addEventListener('scroll', () => {
    if (!ticking) {
      requestAnimationFrame(() => {
        header.classList.toggle('scrolled', window.scrollY > 10);
        ticking = false;
      });
      ticking = true;
    }
  });
}

/* ========== Mobile Navigation ========== */
function initMobileNav() {
  const toggle = document.querySelector('.nav-toggle');
  const mobileNav = document.querySelector('.nav-mobile');
  const overlay = document.querySelector('.overlay');
  const mobileLinks = document.querySelectorAll('.nav-mobile a');

  if (!toggle || !mobileNav || !overlay) return;

  function open() {
    toggle.classList.add('active');
    mobileNav.classList.add('open');
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function close() {
    toggle.classList.remove('active');
    mobileNav.classList.remove('open');
    overlay.classList.remove('active');
    document.body.style.overflow = '';
  }

  toggle.addEventListener('click', () => {
    mobileNav.classList.contains('open') ? close() : open();
  });

  overlay.addEventListener('click', close);
  mobileLinks.forEach(link => link.addEventListener('click', close));
}

/* ========== Pricing Toggle ========== */
function initPricingToggle() {
  const toggle = document.querySelector('.toggle-switch');
  if (!toggle) return;

  const monthlyLabel = document.querySelector('.pricing-toggle .monthly-label');
  const annualLabel = document.querySelector('.pricing-toggle .annual-label');
  const starterPrice = document.querySelector('.starter-price');
  const premiumPrice = document.querySelector('.premium-price');
  const starterPeriod = document.querySelector('.starter-period');
  const premiumPeriod = document.querySelector('.premium-period');
  const starterNote = document.querySelector('.starter-note');
  const premiumNote = document.querySelector('.premium-note');

  const prices = {
    monthly: { starter: '$29.99', premium: '$69.99' },
    annual: { starter: '$23.99', premium: '$55.99' }
  };

  toggle.addEventListener('click', () => {
    const isAnnual = toggle.classList.toggle('active');

    if (monthlyLabel) monthlyLabel.classList.toggle('active', !isAnnual);
    if (annualLabel) annualLabel.classList.toggle('active', isAnnual);

    if (starterPrice) starterPrice.textContent = isAnnual ? prices.annual.starter : prices.monthly.starter;
    if (premiumPrice) premiumPrice.textContent = isAnnual ? prices.annual.premium : prices.monthly.premium;

    if (starterPeriod) starterPeriod.textContent = isAnnual ? '/month, billed annually' : '/month';
    if (premiumPeriod) premiumPeriod.textContent = isAnnual ? '/month, billed annually' : '/month';

    if (starterNote) starterNote.textContent = isAnnual ? 'Save 20% with annual billing' : '';
    if (premiumNote) premiumNote.textContent = isAnnual ? 'Save 20% with annual billing' : '';
  });
}

/* ========== FAQ Accordion ========== */
function initFAQAccordion() {
  const faqItems = document.querySelectorAll('.faq-item');

  faqItems.forEach(item => {
    const question = item.querySelector('.faq-question');
    if (!question) return;

    question.addEventListener('click', () => {
      const isOpen = item.classList.contains('open');

      // Close all others
      faqItems.forEach(other => {
        if (other !== item) other.classList.remove('open');
      });

      // Toggle current
      item.classList.toggle('open', !isOpen);
    });
  });
}

/* ========== Testimonial Carousel ========== */
function initTestimonialCarousel() {
  const track = document.querySelector('.testimonial-track');
  if (!track) return;

  const cards = track.querySelectorAll('.testimonial-card');
  const prevBtn = document.querySelector('.testimonial-prev');
  const nextBtn = document.querySelector('.testimonial-next');
  const dots = document.querySelectorAll('.testimonial-dot');

  let current = 0;
  const total = cards.length;

  function goTo(index) {
    current = (index + total) % total;
    track.style.transform = `translateX(-${current * 100}%)`;

    dots.forEach((dot, i) => {
      dot.classList.toggle('active', i === current);
    });
  }

  if (prevBtn) prevBtn.addEventListener('click', () => goTo(current - 1));
  if (nextBtn) nextBtn.addEventListener('click', () => goTo(current + 1));

  dots.forEach((dot, i) => {
    dot.addEventListener('click', () => goTo(i));
  });

  // Auto-advance every 6 seconds
  setInterval(() => goTo(current + 1), 6000);
}

/* ========== Contact Form ========== */
function initContactForm() {
  const form = document.querySelector('.contact-form');
  if (!form) return;

  const successMessage = document.querySelector('.form-success');

  form.addEventListener('submit', (e) => {
    e.preventDefault();

    let isValid = true;
    const requiredFields = form.querySelectorAll('[required]');

    // Clear previous errors
    form.querySelectorAll('.error-message').forEach(el => el.remove());
    form.querySelectorAll('.error').forEach(el => el.classList.remove('error'));

    requiredFields.forEach(field => {
      const value = field.value.trim();
      let error = '';

      if (!value) {
        error = 'This field is required.';
      } else if (field.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
        error = 'Please enter a valid email address.';
      }

      if (error) {
        isValid = false;
        field.classList.add('error');
        const errorEl = document.createElement('p');
        errorEl.className = 'error-message';
        errorEl.textContent = error;
        field.parentNode.appendChild(errorEl);
      }
    });

    if (isValid) {
      form.style.display = 'none';
      if (successMessage) successMessage.classList.add('show');
    }
  });
}

/* ========== Scroll Animations ========== */
function initScrollAnimations() {
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('animate-in');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });

  document.querySelectorAll('.feature-card, .step, .stat-item, .pricing-card, .team-card, .office-card, .integration-category').forEach(el => {
    el.style.opacity = '0';
    observer.observe(el);
  });
}

/* ========== Count-Up Animation ========== */
function initCountUp() {
  const statNumbers = document.querySelectorAll('.stat-number');
  if (!statNumbers.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        const raw = el.dataset.value || el.textContent;
        const numeric = parseFloat(raw.replace(/[^0-9.]/g, ''));
        const suffix = raw.replace(/[0-9.,]/g, '');
        const duration = 1500;
        const start = performance.now();

        function update(now) {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          const current = Math.floor(numeric * eased);

          if (raw.includes('.')) {
            el.textContent = (numeric * eased).toFixed(1) + suffix;
          } else {
            el.textContent = current.toLocaleString() + suffix;
          }

          if (progress < 1) {
            requestAnimationFrame(update);
          } else {
            el.textContent = raw;
          }
        }

        requestAnimationFrame(update);
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.5 });

  statNumbers.forEach(el => observer.observe(el));
}
